}

func (a *Agent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
	var out []byte
	for _, chunk := range chunks {
		out = append(out, chunk...)
	}
	return out, nil
}

func (a *Agent) FormatResumeCommand(id string) string { return "hermes --resume " + shellQuote(id) }

func shellQuote(value string) string { return "'" + strings.ReplaceAll(value, "'", "'\\''") + "'" }

func (a *Agent) ParseHook(hook string, input []byte) (*protocol.EventJSON, error) {
	if len(strings.TrimSpace(string(input))) == 0 {
		return nil, nil
	}
	var raw struct {
		SessionID  string `json:"session_id"`
		SessionRef string `json:"session_ref"`
		Timestamp  string `json:"timestamp"`
		Prompt     string `json:"prompt"`
		UserPrompt string `json:"user_prompt"`
		Model      string `json:"model"`
	}
	if err := json.Unmarshal(input, &raw); err != nil {
		return nil, err
	}
	if raw.SessionID == "" {
		return nil, nil
	}
	if raw.Timestamp == "" {
		raw.Timestamp = time.Now().UTC().Format(time.RFC3339)
	}
	if raw.Prompt == "" {
		raw.Prompt = raw.UserPrompt
	}
	raw.Prompt = sanitizeText(raw.Prompt)
	raw.Model = sanitizeModel(raw.Model)
	types := map[string]int{"on_session_start": 1, "pre_llm_call": 2, "on_session_end": 3, "on_session_finalize": 5}
	typ := types[hook]
	if typ == 0 {
		return nil, nil
	}
	if raw.SessionRef == "" {
		dir, err := a.GetSessionDir(protocol.RepoRoot())
		if err == nil {
			raw.SessionRef = a.ResolveSessionFile(dir, raw.SessionID)
		}
	}
	return &protocol.EventJSON{Type: typ, SessionID: raw.SessionID, SessionRef: raw.SessionRef, Prompt: raw.Prompt, Model: raw.Model, Timestamp: raw.Timestamp}, nil
}

func (a *Agent) GetTranscriptPosition(path string) (int, error) {
	resolved, err := resolveTranscriptPath(path, false)
	if errors.Is(err, errTranscriptPathNotOwned) {
		return 0, nil
	}
	if err != nil {
		return 0, err
	}
	position, err := transcriptFileLineCount(resolved)
	if errors.Is(err, os.ErrNotExist) {
		return 0, nil
	}
	if err != nil {
		return 0, err
	}
	return position, nil
}
package hermes

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"

	"gopkg.in/yaml.v3"
)

func loadConfig(path string) (*yaml.Node, error) {
	root := &yaml.Node{Kind: yaml.DocumentNode}
	mapping := &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"}
	root.Content = []*yaml.Node{mapping}

	data, err := os.ReadFile(path)
	if errors.Is(err, os.ErrNotExist) {
		return root, nil
	}
	if err != nil {
		return nil, fmt.Errorf("read Hermes config: %w", err)
	}
	if len(data) == 0 {
		return root, nil
	}
	if err := yaml.Unmarshal(data, root); err != nil {
		return nil, fmt.Errorf("parse Hermes config without modifying it: %w", err)
	}
	if len(root.Content) != 1 || root.Content[0].Kind != yaml.MappingNode {
		return nil, errors.New("hermes config must contain a YAML mapping")
	}
	return root, nil
}

func mappingValue(mapping *yaml.Node, key string) *yaml.Node {
	if mapping == nil || mapping.Kind != yaml.MappingNode {
		return nil
	}
	for i := 0; i+1 < len(mapping.Content); i += 2 {
		if mapping.Content[i].Value == key {
			return mapping.Content[i+1]
		}
	}
	return nil
}

func ensureMappingValue(mapping *yaml.Node, key string) (*yaml.Node, error) {
	if value := mappingValue(mapping, key); value != nil {
		if value.Kind != yaml.MappingNode {
			return nil, fmt.Errorf("hermes config %q must be a mapping", key)
		}
		return value, nil
	}
	keyNode := &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: key}
	valueNode := &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"}
	mapping.Content = append(mapping.Content, keyNode, valueNode)
	return valueNode, nil
}

func sequenceValue(mapping *yaml.Node, key string, create bool) (*yaml.Node, error) {
	if value := mappingValue(mapping, key); value != nil {
		if value.Kind != yaml.SequenceNode {
			return nil, fmt.Errorf("hermes config plugins.%s must be a sequence", key)
		}
		return value, nil
	}
	if !create {
		return nil, nil
	}
	keyNode := &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: key}
	valueNode := &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq"}
	mapping.Content = append(mapping.Content, keyNode, valueNode)
	return valueNode, nil
}

func sequenceContains(sequence *yaml.Node, item string) bool {
	if sequence == nil {
		return false
	}
	for _, node := range sequence.Content {
		if node.Kind == yaml.ScalarNode && node.Value == item {
			return true
		}
	}
	return false
}

func sequenceRemove(sequence *yaml.Node, item string) bool {
	if sequence == nil {
		return false
	}
	filtered := sequence.Content[:0]
	removed := false
	for _, node := range sequence.Content {
		if node.Kind == yaml.ScalarNode && node.Value == item {
			removed = true
			continue
		}
		filtered = append(filtered, node)
	}
	sequence.Content = filtered
	return removed
}

func updatePluginConfig(home string, enabled bool) (bool, error) {
	path := filepath.Join(home, "config.yaml")
	root, err := loadConfig(path)
	if err != nil {
		return false, err
	}
	mapping := root.Content[0]
	plugins := mappingValue(mapping, "plugins")
	if plugins == nil && !enabled {
		return false, nil
	}
	if plugins == nil {
		plugins, err = ensureMappingValue(mapping, "plugins")
	} else if plugins.Kind != yaml.MappingNode {
		return false, errors.New("hermes config plugins must be a mapping")
	}
	if err != nil {
		return false, err
	}
	enabledList, err := sequenceValue(plugins, "enabled", enabled)
	if err != nil {
		return false, err
	}
	disabledList, err := sequenceValue(plugins, "disabled", false)
	if err != nil {
		return false, err
	}

	changed := false
	if enabled {
		if !sequenceContains(enabledList, pluginName) {
			enabledList.Content = append(enabledList.Content, &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: pluginName})
			changed = true
		}
		changed = sequenceRemove(disabledList, pluginName) || changed
	} else {
		changed = sequenceRemove(enabledList, pluginName)
	}
	if !changed {
		return false, nil
	}
	data, err := yaml.Marshal(root)
	if err != nil {
		return false, fmt.Errorf("encode Hermes config: %w", err)
	}
	if err := atomicWrite(path, data, 0o600); err != nil {
		return false, fmt.Errorf("update Hermes config: %w", err)
	}
	return true, nil
}

func pluginEnabled(home string) bool {
	root, err := loadConfig(filepath.Join(home, "config.yaml"))
	if err != nil {
		return false
	}
	plugins := mappingValue(root.Content[0], "plugins")
	if plugins == nil || plugins.Kind != yaml.MappingNode {
		return false
	}
	enabled, err := sequenceValue(plugins, "enabled", false)
	if err != nil || !sequenceContains(enabled, pluginName) {
		return false
	}
	disabled, err := sequenceValue(plugins, "disabled", false)
	return err == nil && !sequenceContains(disabled, pluginName)
}
package hermes

import (
	"embed"
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

const (
	pluginName   = "entire-observer"
	pluginMarker = "entire-agent-hermes observer v1"
)

var observerHooks = []string{
	"on_session_start",
	"pre_llm_call",
	"pre_tool_call",
	"post_tool_call",
	"post_llm_call",
	"on_session_end",
	"on_session_finalize",
}

//go:embed plugin/plugin.yaml plugin/__init__.py
var pluginFiles embed.FS

type repositoryRegistration struct {
	Path      string `json:"path"`
	EntireBin string `json:"entire_bin"`
}

type repositoryRegistry struct {
	Version      int                      `json:"version"`
	Repositories []repositoryRegistration `json:"repositories"`
}

func pluginDir(home string) string { return filepath.Join(home, "plugins", pluginName) }

func registryPath(home string) string { return filepath.Join(pluginDir(home), "repositories.json") }

func loadRegistry(home string) (repositoryRegistry, error) {
	registry := repositoryRegistry{Version: 1, Repositories: []repositoryRegistration{}}
	data, err := os.ReadFile(registryPath(home))
	if errors.Is(err, os.ErrNotExist) {
		return registry, nil
	}
	if err != nil {
		return registry, fmt.Errorf("read Hermes observer registry: %w", err)
	}
	if err := json.Unmarshal(data, &registry); err != nil {
		return registry, fmt.Errorf("parse Hermes observer registry: %w", err)
	}
	if registry.Version != 1 {
		return registry, fmt.Errorf("unsupported Hermes observer registry version %d", registry.Version)
	}
	if registry.Repositories == nil {
		registry.Repositories = []repositoryRegistration{}
	}
	return registry, nil
}

func saveRegistry(home string, registry repositoryRegistry) error {
	registry.Version = 1
	data, err := json.MarshalIndent(registry, "", "  ")
	if err != nil {
		return err
	}
	data = append(data, '\n')
	return atomicWrite(registryPath(home), data, 0o600)
}

func resolvedEntireBinary() (string, error) {
	path, err := exec.LookPath("entire")
	if err != nil {
		return "", errors.New("entire executable was not found in PATH")
	}
	return canonicalPath(path)
}

func ensureOwnedOrMissing(path string) error {
	data, err := os.ReadFile(path)
	if errors.Is(err, os.ErrNotExist) {
		return nil
	}
	if err != nil {
		return fmt.Errorf("inspect existing Hermes plugin file %s: %w", path, err)
	}
	if !strings.Contains(string(data), pluginMarker) {
		return fmt.Errorf("refusing to overwrite non-owned Hermes plugin file %s", path)
	}
	return nil
}

func (a *Agent) InstallHooks(_ bool, force bool) (int, error) {
	home, err := explicitHome()
	if err != nil {
		return 0, err
	}
	repo, err := canonicalPath(protocolRepoRoot())
	if err != nil {
		return 0, fmt.Errorf("resolve repository: %w", err)
	}
	entireBin, err := resolvedEntireBinary()
	if err != nil {
		return 0, err
	}
	registry, err := loadRegistry(home)
	if err != nil {
		return 0, err
	}

	changed := force
	for _, name := range []string{"plugin.yaml", "__init__.py"} {
		if err := ensureOwnedOrMissing(filepath.Join(pluginDir(home), name)); err != nil {
			return 0, err
		}
	}
	for _, name := range []string{"plugin.yaml", "__init__.py"} {
		destination := filepath.Join(pluginDir(home), name)
		data, readErr := fs.ReadFile(pluginFiles, "plugin/"+name)
		if readErr != nil {
			return 0, readErr
		}
		fileChanged, writeErr := writeIfChanged(destination, data, 0o600, force)
		if writeErr != nil {
			return 0, fmt.Errorf("install Hermes observer %s: %w", name, writeErr)
		}
		changed = fileChanged || changed
	}

	found := false
	for i := range registry.Repositories {
		if registry.Repositories[i].Path == repo {
			found = true
			if registry.Repositories[i].EntireBin != entireBin {
				registry.Repositories[i].EntireBin = entireBin
				changed = true
			}
			break
		}
	}
	if !found {
		registry.Repositories = append(registry.Repositories, repositoryRegistration{Path: repo, EntireBin: entireBin})
		changed = true
	}
	if changed {
		if err := saveRegistry(home, registry); err != nil {
			return 0, fmt.Errorf("register repository with Hermes observer: %w", err)
		}
	}
	configChanged, err := updatePluginConfig(home, true)
	if err != nil {
		return 0, err
	}
	changed = configChanged || changed
	if !changed {
		return 0, nil
	}
	return len(observerHooks), nil
}

func (a *Agent) UninstallHooks() error {
	home, err := explicitHome()
	if err != nil {
		return err
	}
	repo, err := canonicalPath(protocolRepoRoot())
	if err != nil {
		return err
	}
	registry, err := loadRegistry(home)
	if err != nil {
		return err
	}
	remaining := registry.Repositories[:0]
	for _, entry := range registry.Repositories {
		if entry.Path != repo {
			remaining = append(remaining, entry)
		}
	}
	registry.Repositories = remaining
	if len(remaining) > 0 {
		return saveRegistry(home, registry)
	}

	if _, err := updatePluginConfig(home, false); err != nil {
		return err
	}
	for _, path := range []string{
		filepath.Join(pluginDir(home), "plugin.yaml"),
		filepath.Join(pluginDir(home), "__init__.py"),
		registryPath(home),
	} {
		if err := removeOwnedFile(path); err != nil {
			return err
		}
	}
	if err := os.Remove(pluginDir(home)); err != nil && !errors.Is(err, os.ErrNotExist) && !isNotEmpty(err) {
		return err
	}
	return nil
}

func (a *Agent) AreHooksInstalled() bool {
	home, err := explicitHome()
	if err != nil || !pluginEnabled(home) {
		return false
	}
	repo, err := canonicalPath(protocolRepoRoot())
	if err != nil {
		return false
	}
	registry, err := loadRegistry(home)
	if err != nil {
		return false
	}
	found := false
	for _, entry := range registry.Repositories {
		if entry.Path == repo && entry.EntireBin != "" {
			found = true
			break
		}
	}
	if !found {
		return false
	}
	for _, name := range []string{"plugin.yaml", "__init__.py"} {
		data, err := os.ReadFile(filepath.Join(pluginDir(home), name))
		if err != nil || !strings.Contains(string(data), pluginMarker) {
			return false
		}
	}
	return true
}

func protocolRepoRoot() string {
	if root := strings.TrimSpace(os.Getenv("ENTIRE_REPO_ROOT")); root != "" {
		return root
	}
	root, _ := os.Getwd()
	return root
}

func writeIfChanged(path string, data []byte, mode os.FileMode, force bool) (bool, error) {
	existing, err := os.ReadFile(path)
	if err == nil && string(existing) == string(data) && !force {
		return false, os.Chmod(path, mode)
	}
	if err != nil && !errors.Is(err, os.ErrNotExist) {
		return false, err
	}
	return true, atomicWrite(path, data, mode)
}

func atomicWrite(path string, data []byte, mode os.FileMode) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		return err
	}
	tmp, err := os.CreateTemp(filepath.Dir(path), ".entire-agent-hermes-*")
	if err != nil {
		return err
	}
	tmpPath := tmp.Name()
	defer os.Remove(tmpPath)
	if err := tmp.Chmod(mode); err != nil {
		return closeTemporary(tmp, err)
	}
	if _, err := tmp.Write(data); err != nil {
		return closeTemporary(tmp, err)
	}
	if err := tmp.Sync(); err != nil {
		return closeTemporary(tmp, err)
	}
	if err := tmp.Close(); err != nil {
		return err
	}
	return os.Rename(tmpPath, path)
}

func closeTemporary(file *os.File, cause error) error {
	if closeErr := file.Close(); closeErr != nil {
		return errors.Join(cause, closeErr)
	}
	return cause
}

func removeOwnedFile(path string) error {
	data, err := os.ReadFile(path)
	if errors.Is(err, os.ErrNotExist) {
		return nil
	}
	if err != nil {
		return err
	}
	if filepath.Base(path) != "repositories.json" && !strings.Contains(string(data), pluginMarker) {
		return fmt.Errorf("refusing to remove modified non-owned file %s", path)
	}
	return os.Remove(path)
}

func isNotEmpty(err error) bool {
	return strings.Contains(strings.ToLower(err.Error()), "not empty")
}
"}

