package agents

import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"syscall"
	"time"
)

func init() {
	if os.Getenv("HERMES_E2E") != "1" || os.Getenv("E2E_AGENT") != "hermes" {
		return
	}
	Register(&Hermes{})
	RegisterGate("hermes", 1)
}

type Hermes struct{}

func (h *Hermes) Name() string               { return "hermes" }
func (h *Hermes) Binary() string             { return "hermes" }
func (h *Hermes) EntireAgent() string        { return "hermes" }
func (h *Hermes) PromptPattern() string      { return `❯` }
func (h *Hermes) TimeoutMultiplier() float64 { return 2.0 }
func (h *Hermes) IsExternalAgent() bool      { return true }

func (h *Hermes) Bootstrap() error {
	homeValue := strings.TrimSpace(os.Getenv("HERMES_HOME"))
	if homeValue == "" {
		return errors.New("Hermes E2E requires an explicit disposable HERMES_HOME")
	}
	home, err := filepath.Abs(homeValue)
	if err != nil {
		return fmt.Errorf("resolve HERMES_HOME: %w", err)
	}
	if resolved, resolveErr := filepath.EvalSymlinks(home); resolveErr == nil {
		home = resolved
	}
	userHome, err := os.UserHomeDir()
	if err == nil {
		realProfile := filepath.Join(userHome, ".hermes")
		if resolved, resolveErr := filepath.EvalSymlinks(realProfile); resolveErr == nil {
			realProfile = resolved
		}
		rel, relErr := filepath.Rel(realProfile, home)
		if relErr == nil && rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
			return fmt.Errorf("Hermes E2E refuses the real profile tree %s", realProfile)
		}
	}
	return nil
}

func (h *Hermes) IsTransientError(out Output, _ error) bool {
	combined := strings.ToLower(out.Stdout + out.Stderr)
	for _, pattern := range []string{"overloaded", "rate limit", "429", "500", "503", "529", "econnreset", "etimedout", "timeout"} {
		if strings.Contains(combined, pattern) {
			return true
		}
	}
	return false
}

func (h *Hermes) RunPrompt(ctx context.Context, dir, prompt string, _ ...Option) (Output, error) {
	if err := h.Bootstrap(); err != nil {
		return Output{}, err
	}
	bin, err := exec.LookPath(h.Binary())
	if err != nil {
		return Output{}, fmt.Errorf("%s not in PATH: %w", h.Binary(), err)
	}
	args := []string{"--yolo", "--ignore-rules", "-z", prompt}
	displayArgs := []string{"--yolo", "--ignore-rules", "-z", fmt.Sprintf("%q", prompt)}
	cmd := exec.CommandContext(ctx, bin, args...)
	cmd.Dir = dir
	cmd.Env = filterEnv(os.Environ(), "ENTIRE_TEST_TTY")
	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
	cmd.Cancel = func() error { return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL) }
	cmd.WaitDelay = 5 * time.Second
	var stdout, stderr strings.Builder
	cmd.Stdout, cmd.Stderr = &stdout, &stderr
	err = cmd.Run()
	exitCode := 0
	if err != nil {
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) {
			exitCode = exitErr.ExitCode()
		} else {
			exitCode = -1
		}
	}
	return Output{Command: h.Binary() + " " + strings.Join(displayArgs, " "), Stdout: stdout.String(), Stderr: stderr.String(), ExitCode: exitCode}, err
}

func (h *Hermes) StartSession(_ context.Context, dir string) (Session, error) {
	if err := h.Bootstrap(); err != nil {
		return nil, err
	}
	name := fmt.Sprintf("hermes-test-%d", time.Now().UnixNano())
	session, err := NewTmuxSession(
		name,
		dir,
		[]string{"ENTIRE_TEST_TTY"},
		h.Binary(),
		"--cli",
		"--yolo",
		"--ignore-rules",
	)
	if err != nil {
		return nil, err
	}
	if _, err := session.WaitFor(h.PromptPattern(), 45*time.Second); err != nil {
		_ = session.Close()
		return nil, fmt.Errorf("waiting for initial prompt: %w", err)
	}
	session.stableAtSend = ""
	return session, nil
}
package protocol

import (
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"strconv"
)

type Agent interface {
	Info() InfoResponse
	Detect() DetectResponse
	GetSessionID(*HookInputJSON) string
	GetSessionDir(string) (string, error)
	ResolveSessionFile(string, string) string
	ReadSession(*HookInputJSON) (AgentSessionJSON, error)
	WriteSession(AgentSessionJSON) error
	ReadTranscript(string) ([]byte, error)
	ChunkTranscript([]byte, int) ([][]byte, error)
	ReassembleTranscript([][]byte) ([]byte, error)
	CompactTranscript(string) (CompactTranscriptResponse, error)
	PrepareTranscript(string) error
	FormatResumeCommand(string) string
	ParseHook(string, []byte) (*EventJSON, error)
	InstallHooks(bool, bool) (int, error)
	UninstallHooks() error
	AreHooksInstalled() bool
	GetTranscriptPosition(string) (int, error)
	ExtractModifiedFiles(string, int) ([]string, int, error)
	ExtractPrompts(string, int) ([]string, error)
	ExtractSummary(string) (string, bool, error)
}

func WriteJSON(w io.Writer, v any) error {
	enc := json.NewEncoder(w)
	enc.SetEscapeHTML(false)
	return enc.Encode(v)
}

func RepoRoot() string {
	if root := os.Getenv("ENTIRE_REPO_ROOT"); root != "" {
		return root
	}
	root, _ := os.Getwd()
	return root
}

func Run(agent Agent, args []string, stdin io.Reader, stdout io.Writer) error {
	if len(args) == 0 {
		return errors.New("usage: entire-agent-hermes <subcommand> [args]")
	}
	switch args[0] {
	case "info":
		return WriteJSON(stdout, agent.Info())
	case "detect":
		return WriteJSON(stdout, agent.Detect())
	case "get-session-id":
		var in HookInputJSON
		if err := json.NewDecoder(stdin).Decode(&in); err != nil {
			return err
		}
		return WriteJSON(stdout, SessionIDResponse{SessionID: agent.GetSessionID(&in)})
	case "get-session-dir":
		fs := newFlags(args[0])
		repo := fs.String("repo-path", "", "repo path")
		if err := fs.Parse(args[1:]); err != nil {
			return err
		}
		dir, err := agent.GetSessionDir(*repo)
		if err != nil {
			return err
		}
		return WriteJSON(stdout, SessionDirResponse{SessionDir: dir})
	case "resolve-session-file":
		fs := newFlags(args[0])
		dir := fs.String("session-dir", "", "session dir")
		id := fs.String("session-id", "", "session id")
		if err := fs.Parse(args[1:]); err != nil {
			return err
		}
		return WriteJSON(stdout, SessionFileResponse{SessionFile: agent.ResolveSessionFile(*dir, *id)})
	case "read-session":
		var in HookInputJSON
		if err := json.NewDecoder(stdin).Decode(&in); err != nil {
			return err
		}
		session, err := agent.ReadSession(&in)
		if err != nil {
			return err
		}
		return WriteJSON(stdout, session)
	case "write-session":
		var in AgentSessionJSON
		if err := json.NewDecoder(stdin).Decode(&in); err != nil {
			return err
		}
		return agent.WriteSession(in)
	case "read-transcript":
		fs := newFlags(args[0])
		ref := fs.String("session-ref", "", "session ref")
		if err := fs.Parse(args[1:]); err != nil {
			return err
		}
		data, err := agent.ReadTranscript(*ref)
		if err != nil {
			return err
		}
		_, err = stdout.Write(data)
		return err
	case "chunk-transcript":
		fs := newFlags(args[0])
		maxSize := fs.Int("max-size", 0, "max size")
		if err := fs.Parse(args[1:]); err != nil {
			return err
		}
		data, err := io.ReadAll(stdin)
		if err != nil {
			return err
		}
		chunks, err := agent.ChunkTranscript(data, *maxSize)
		if err != nil {
			return err
		}
		return WriteJSON(stdout, ChunkResponse{Chunks: chunks})
	case "reassemble-transcript":
		var in ChunkResponse
		if err := json.NewDecoder(stdin).Decode(&in); err != nil {
			return err
		}
		data, err := agent.ReassembleTranscript(in.Chunks)
		if err != nil {
			return err
		}
		_, err = stdout.Write(data)
		return err
	case "compact-transcript":
		fs := newFlags(args[0])
		ref := fs.String("session-ref", "", "session ref")
		if err := fs.Parse(args[1:]); err != nil {
			return err
		}
		out, err := agent.CompactTranscript(*ref)
		if err != nil {
			return err
		}
		return WriteJSON(stdout, out)
	case "prepare-transcript":
		fs := newFlags(args[0])
		ref := fs.String("session-ref", "", "session ref")
		if err := fs.Parse(args[1:]); err != nil {
			return err
		}
		return agent.PrepareTranscript(*ref)
	case "format-resume-command":
		fs := newFlags(args[0])
		id := fs.String("session-id", "", "session id")
		if err := fs.Parse(args[1:]); err != nil {
			return err
		}
		return WriteJSON(stdout, ResumeCommandResponse{Command: agent.FormatResumeCommand(*id)})
	case "parse-hook":
		fs := newFlags(args[0])
		hook := fs.String("hook", "", "hook name")
		if err := fs.Parse(args[1:]); err != nil {
			return err
		}
		data, err := io.ReadAll(stdin)
		if err != nil {
			return err
		}
		event, err := agent.ParseHook(*hook, data)
		if err != nil {
			return err
		}
		if event == nil {
			_, err = io.WriteString(stdout, "null\n")
			return err
		}
		return WriteJSON(stdout, event)
	case "install-hooks":
		fs := newFlags(args[0])
		local := fs.Bool("local-dev", false, "local dev")
		force := fs.Bool("force", false, "force")
		if err := fs.Parse(args[1:]); err != nil {
			return err
		}
		count, err := agent.InstallHooks(*local, *force)
		if err != nil {
			return err
		}
		return WriteJSON(stdout, HooksInstalledCountResponse{HooksInstalled: count})
	case "uninstall-hooks":
		return agent.UninstallHooks()
	case "are-hooks-installed":
		return WriteJSON(stdout, AreHooksInstalledResponse{Installed: agent.AreHooksInstalled()})
	case "get-transcript-position":
		fs := newFlags(args[0])
		path := fs.String("path", "", "path")
		if err := fs.Parse(args[1:]); err != nil {
			return err
		}
		position, err := agent.GetTranscriptPosition(*path)
		if err != nil {
			return err
		}
		return WriteJSON(stdout, TranscriptPositionResponse{Position: position})
	case "extract-modified-files":
		fs := newFlags(args[0])
		path := fs.String("path", "", "path")
		offset := fs.Int("offset", 0, "offset")
		if err := fs.Parse(args[1:]); err != nil {
			return err
		}
		files, position, err := agent.ExtractModifiedFiles(*path, *offset)
		if err != nil {
			return err
		}
		return WriteJSON(stdout, ExtractFilesResponse{Files: files, CurrentPosition: position})
	case "extract-prompts":
		fs := newFlags(args[0])
		ref := fs.String("session-ref", "", "session ref")
		offset := fs.Int("offset", 0, "offset")
		if err := fs.Parse(args[1:]); err != nil {
			return err
		}
		prompts, err := agent.ExtractPrompts(*ref, *offset)
		if err != nil {
			return err
		}
		return WriteJSON(stdout, ExtractPromptsResponse{Prompts: prompts})
	case "extract-summary":
		fs := newFlags(args[0])
		ref := fs.String("session-ref", "", "session ref")
		if err := fs.Parse(args[1:]); err != nil {
			return err
		}
		summary, ok, err := agent.ExtractSummary(*ref)
		if err != nil {
			return err
		}
		return WriteJSON(stdout, ExtractSummaryResponse{Summary: summary, HasSummary: ok})
	default:
		return fmt.Errorf("unknown subcommand: %s", args[0])
	}
}

func newFlags(name string) *flag.FlagSet {
	fs := flag.NewFlagSet(name, flag.ContinueOnError)
	fs.SetOutput(io.Discard)
	return fs
}

func ParseOffset(raw string) (int, error) {
	n, err := strconv.Atoi(raw)
	if err != nil || n < 0 {
		return 0, fmt.Errorf("invalid offset %q", raw)
	}
	return n, nil
}
