+		if entry.Type == entryTypeUser && entry.Content != "" {
 			prompts = append(prompts, entry.Content)
 		}
 	}
@@ -435,7 +440,7 @@ func (a *Agent) ExtractSummary(path string) (string, bool, error) {
 		return "", false, err
